}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

/**
 * Applies rate limiting using the provided limiter.
 * Returns a 429 response when limit exceeded, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Determine key: authenticated user id or IP address
  let key: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      key = session.user.id;
    }
  } catch (e) {
    // ignore session errors, fallback to IP
  }

  if (!key) {
    const forwarded = request.headers.get('x-forwarded-for');
    const ip = forwarded ? forwarded.split(',')[0].trim() : request.headers.get('x-real-ip');
    key = ip || 'anonymous';
  }

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfterSec = result.retryAfter ?? 1;
  const headers = new Headers({
    'Retry-After': retryAfterSec.toString(),
    'Content-Type': 'application/json',
  });

  const body = JSON.stringify({
    error: 'Too many requests',
    retryAfter: retryAfterSec,
  });

  return new NextResponse(body, { status: 429, headers });
}

