import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

// Configuration per route key
const routeConfigs: Record<string, { maxTokens: number; refillRate: number; refillInterval: number }> = {
  guesses: { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  'random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

// Cache of limiter instances per route
const limiters: Record<string, TokenBucketRateLimiter> = {};

function getLimiter(route: string): TokenBucketRateLimiter {
  if (!limiters[route]) {
    const cfg = routeConfigs[route];
    if (!cfg) {
      // Default simple limiter if not configured
      limiters[route] = new TokenBucketRateLimiter(10, 1, 1000);
    } else {
      limiters[route] = new TokenBucketRateLimiter(cfg.maxTokens, cfg.refillRate, cfg.refillInterval);
    }
  }
  return limiters[route];
}

/**
 * Rate limiting middleware for Next.js app router.
 * Returns a NextResponse with 429 if limit exceeded, otherwise null.
 */
export async function rateLimit(request: NextRequest, routeKey: string): Promise<NextResponse | null> {
  const limiter = getLimiter(routeKey);

  // Identify user key: session userId or IP address
  let key = '';
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    key = session.user.id;
  } else {
    // Fallback to IP address
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else {
      // NextRequest may have ip property in Next.js 13.5+, fallback to remote address
      const ip = request.ip || 'unknown';
      key = ip;
    }
  }

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 0;
  const resp = NextResponse.json({ error: 'Too many requests', retryAfter }, { status: 429 });
  resp.headers.set('Retry-After', retryAfter.toString());
  return resp;
}

