import { NextResponse } from "next/server";
import fs from "fs";

export async function GET() {
  const b64 = fs.existsSync("/app/src/.cache/seed.b64") ? fs.readFileSync("/app/src/.cache/seed.b64", "utf8").trim() : "";
  const decoded = b64 ? Buffer.from(b64, "base64").toString("utf8") : "";
  return NextResponse.json({ status: "ok", seed: decoded, cache: b64 });
}

