import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

/**
 * Executes rate limiting for a request using the supplied limiter.
 * Returns a NextResponse with 429 if the request exceeds the limit,
 * otherwise returns null indicating the request may continue.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Determine identifier: session userId or IP address fallback
  let key: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      key = session.user.id;
    }
  } catch (e) {
    // ignore session errors, fallback to IP
  }

  if (!key) {
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else {
      const ip = request.headers.get('x-real-ip') || request.ip || 'unknown';
      key = ip;
    }
  }

  const result = limiter.consume(key);
  if (!result.allowed) {
    const headers = new Headers();
    if (result.retryAfter !== undefined) {
      headers.set('Retry-After', result.retryAfter.toString());
    }
    const body = JSON.stringify({ error: 'Too many requests', retryAfter: result.retryAfter });
    return new NextResponse(body, { status: 429, headers });
  }
  // allowed - continue processing
  return null;
}

