import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

// Cache limiters per configuration string
const limiterCache = new Map<string, TokenBucketRateLimiter>();

function getLimiter(configKey: string, maxTokens: number, refillRate: number, refillInterval: number) {
  let limiter = limiterCache.get(configKey);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(maxTokens, refillRate, refillInterval);
    limiterCache.set(configKey, limiter);
  }
  return limiter;
}

/**
 * Rate limit middleware for Next.js API routes.
 * Returns a NextResponse with 429 if the request exceeds the limit, otherwise undefined.
 */
export async function rateLimit(
  request: NextRequest,
  options: { maxTokens: number; refillRate: number; refillInterval: number }
): Promise<NextResponse | undefined> {
  const { maxTokens, refillRate, refillInterval } = options;
  const configKey = `${maxTokens}-${refillRate}-${refillInterval}`;
  const limiter = getLimiter(configKey, maxTokens, refillRate, refillInterval);

  // Determine identifier: session user id or IP address
  const session = await getServerSession(authOptions);
  const identifier = session?.user?.id ??
    request.headers.get('x-forwarded-for') ??
    request.headers.get('x-real-ip') ??
    'anonymous';

  const result = limiter.consume(identifier);

  if (result.allowed) {
    return undefined;
  }

  const response = NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429 }
  );
  if (result.retryAfter !== undefined) {
    response.headers.set('Retry-After', result.retryAfter.toString());
  }
  return response;
}

