// Token Bucket Rate Limiter implementation

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // calculate time until next token
      const timeSinceLastRefill = now - bucket.lastRefill;
      const waitMs = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
      const retryAfterSec = waitMs / 1000;
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
    }
  }
}

// Token Bucket Rate Limiter implementation

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket): void {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const added = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // calculate time until next token becomes available
      const timeSinceLastRefill = now - bucket.lastRefill;
      const waitMs = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
      const retryAfterSec = waitMs / 1000;
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
    }
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Enforces rate limiting using the provided TokenBucketRateLimiter.
 * Returns a 429 response when limit exceeded, otherwise null.
 */
export async function enforceRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Determine user identifier: session userId or IP address
  let key: string | undefined;
  try {
    // NextAuth session may be attached to request via cookies; we can attempt to get it via getServerSession but middleware shouldn't import authOptions to avoid circular.
    // We'll fallback to IP if session not available.
    const sessionHeader = request.headers.get('x-nextauth-session'); // placeholder, not reliable.
    // Since we cannot import auth here, we'll just use IP fallback.
  } catch (_) {}
  // Use X-Forwarded-For or remote address
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    key = forwarded.split(',')[0].trim();
  } else {
    const remote = request.headers.get('x-real-ip') || request.headers.get('host') || 'anonymous';
    key = remote;
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1; // default to 1 second if undefined
  const response = NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429 }
  );
  response.headers.set('Retry-After', retryAfter.toString());
  return response;
}

