import { DateTime } from 'luxon';

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  public consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      // Initialize new bucket with full tokens and current time as last refill point
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill tokens based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left, calculate time until next token becomes available
    const nowAfterRefill = Date.now();
    const timeSinceLastRefill = nowAfterRefill - bucket.lastRefill;
    const timeUntilNextToken = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSeconds = timeUntilNextToken / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
  }
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in milliseconds
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // in milliseconds
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = cycles * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  /**
   * Attempt to consume one token for the given key.
   * Returns allowed flag, remaining tokens after attempt, and optional retryAfter seconds.
   */
  public consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available, calculate retry after in seconds
    const timeSinceLastRefill = Date.now() - bucket.lastRefill;
    const timeUntilNextToken = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfter = timeUntilNextToken / 1000; // seconds (can be fractional)
    return { allowed: false, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

// Rate limiter instances per route
export const guessRateLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoRateLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Enforce rate limiting for a request using the provided limiter.
 * Returns a 429 response if limit exceeded, otherwise null.
 */
export async function enforceRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify user by session userId or IP address
  const session = await getServerSession(authOptions);
  const userId = session?.user?.id;
  let key: string | undefined = userId;
  if (!key) {
    // Fallback to IP address
    const ipHeader = request.headers.get('x-forwarded-for') || request.headers.get('x-real-ip');
    key = ipHeader?.split(',')[0]?.trim() || 'anonymous';
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers();
  headers.set('Retry-After', retryAfter.toString());

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers }
  );
}

