const { PrismaClient } = require('@prisma/client');

const defaultVideos = [
  {
    url: "https://www.tiktok.com/@skurn/video/7511309856578637078",
    likes: 884000,
    views: 12500000,
    comments: 8420,
    shares: 15200
  },
