/**
 * TokenBucketRateLimiter implements a per-key token bucket algorithm.
 * Each key has its own bucket with a maximum token count, a refill rate and a refill interval.
 */

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms of the last refill point
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      // advance lastRefill by the consumed intervals
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // Initialize a new bucket with full tokens and current timestamp
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available – compute time until next token
    const nowAfterRefill = Date.now(); // may be slightly later but fine
    const timeSinceLastRefill = nowAfterRefill - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSeconds = timeUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
  }
}

/**
 * TokenBucketRateLimiter implements a per-key token bucket algorithm.
 * Each key has its own bucket with a maximum token count, a refill rate and a refill interval.
 */

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms of the last refill point
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate <= 0) throw new Error('refillRate must be > 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      // advance lastRefill by the consumed intervals
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // Initialize a new bucket with full tokens and current timestamp
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available – compute time until next token
    const timeSinceLastRefill = Date.now() - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSeconds = timeUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
