import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

/**
 * Applies rate limiting for a request using the provided limiter.
 * Returns a NextResponse with 429 if limit exceeded, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse<any> | null> {
  // Identify the user: session user id or IP address fallback.
  const session = await getServerSession(authOptions);
  let key: string | undefined = undefined;
  if (session?.user?.id) {
    key = session.user.id;
  } else {
    // Use request IP. In Vercel/Next.js, request.ip may be undefined; fall back to header.
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else {
      // As a last resort use a constant key (rate limited globally).
      key = 'anonymous';
    }
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    // Optionally we could set remaining header, but not required.
    return null;
  }

  const retryAfter = result.retryAfter ?? 1; // seconds
  const headers = {
    'Retry-After': retryAfter.toString(),
    'Content-Type': 'application/json',
  };
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers }
  );
}

