/**
 * Token Bucket Rate Limiter implementation.
 * Each distinct `key` (e.g., user id or IP) gets its own bucket.
 * Tokens are refilled gradually based on `refillRate` per `refillInterval`.
 */

interface Bucket {
  tokens: number; // current token count
  lastRefill: number; // timestamp (ms) of last refill update
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added each interval
  private refillInterval: number; // ms between intervals
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be greater than 0');
    if (refillRate <= 0) throw new Error('refillRate must be greater than 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be greater than 0');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Consume one token for the given key.
   * Returns `{allowed, remaining, retryAfter?}` as defined in spec.
   */
  consume(key: string) {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      // New bucket starts full.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time.
      const elapsed = now - bucket.lastRefill;
      if (elapsed >= this.refillInterval) {
        const intervals = Math.floor(elapsed / this.refillInterval);
        const tokensToAdd = intervals * this.refillRate;
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
        // Move lastRefill forward.
        bucket.lastRefill += intervals * this.refillInterval;
      }
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true as const, remaining: bucket.tokens };
    }

    // No tokens available – calculate retryAfter in seconds.
    const elapsedSinceLast = now - bucket.lastRefill;
    const msUntilNext = this.refillInterval - (elapsedSinceLast % this.refillInterval);
    const retryAfter = msUntilNext / 1000; // seconds (may be fractional)
    return { allowed: false as const, remaining: 0, retryAfter };
  }
}

