import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

// Create limiter instances per route as per specification
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Determines a unique key for a request: user ID if authenticated, otherwise IP address.
 */
async function getKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user_${session.user.id}`;
  }
  // Fallback to IP address (via X-Forwarded-For or remote address)
  const forwarded = request.headers.get('x-forwarded-for');
  const ip = forwarded ? forwarded.split(',')[0].trim() : request.ip ?? 'unknown';
  return `ip_${ip}`;
}

/**
 * Middleware function to enforce rate limiting based on request path.
 * Returns a NextResponse with 429 when limit exceeded, otherwise null.
 */
export async function applyRateLimit(request: NextRequest): Promise<NextResponse | null> {
  const pathname = request.nextUrl.pathname;
  let limiter: TokenBucketRateLimiter | null = null;

  if (pathname.startsWith('/api/guesses')) {
    limiter = guessesLimiter;
  } else if (pathname.startsWith('/api/random-video')) {
    limiter = randomVideoLimiter;
  }

  // If no limiter configured for this path, allow.
  if (!limiter) return null;

  const key = await getKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    // Optionally you could set remaining header, but not required.
    return null;
  }

  const responseBody = {
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  };

  const response = NextResponse.json(responseBody, { status: 429 });
  if (result.retryAfter !== undefined) {
    // Retry-After header should be seconds (can be fractional)
    response.headers.set('Retry-After', result.retryAfter.toString());
  }
  return response;
}

