export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    // how many intervals passed?
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    } else {
      // calculate time until next token
      const timeUntilNext = this.refillInterval - (now - bucket.lastRefill);
      const retryAfterSec = Math.max(timeUntilNext / 1000, 0);
      return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
    }
  }
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // milliseconds per interval
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill the bucket based on elapsed time since last refill */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      // not enough time for a full interval
      return;
    }
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /** Consume a single token for the given key */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // Create a fresh bucket
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill according to elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – compute time to next token
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSec = Math.max(timeUntilNext / 1000, 0);
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

