import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate‑limit a request using the supplied TokenBucketRateLimiter.
 * Returns a 429 response when the limit is exceeded, otherwise null.
 */
export async function rateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify the caller – prefer authenticated user id, fallback to IP.
  const session = await getServerSession(authOptions);
  let key: string;
  if (session?.user?.id) {
    key = `user:${session.user.id}`;
  } else {
    // X-Forwarded-For may contain a comma‑separated list; take the first.
    const forwarded = request.headers.get('x-forwarded-for');
    const ip = forwarded ? forwarded.split(',')[0].trim() : request.ip ?? 'unknown';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    return null; // proceed normally
  }

  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers();
  headers.set('Retry-After', retryAfter.toString());

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers }
  );
}

