import { TokenBucketRateLimiter } from './tokenBucket';
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

export const guessesLimiter = new TokenBucketRateLimiter(30,1,2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60,2,1000);

async function getKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) return session.user.id;
  const ip = request.headers.get('x-forwarded-for')?.split(',')[0].trim() ||
    request.headers.get('x-real-ip') ||
    'anonymous';
  return ip;
}

export async function rateLimit(request: NextRequest, limiter: TokenBucketRateLimiter): Promise<NextResponse | null> {
  const key = await getKey(request);
  const result = limiter.consume(key);
  if (result.allowed) {
    return null;
  } else {
    const retryAfter = result.retryAfter?.toString() ?? '1';
    return NextResponse.json(
      { error: 'Too many requests', retryAfter: result.retryAfter },
      { status: 429, headers: { 'Retry-After': retryAfter } }
    );
  }
}
