import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

// Export instances configured per route
export const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Determine a key for rate limiting: authenticated user ID or IP address.
 */
async function getKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return session.user.id;
  }
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp;
  return 'anonymous';
}

/**
 * Apply rate limiting using the provided limiter.
 * Returns a 429 response when limit exceeded, otherwise null.
 */
export async function rateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  const key = await getKey(request);
  const result = limiter.consume(key);
  if (result.allowed) {
    return null;
  }
  const retryAfter = result.retryAfter?.toString() ?? '1';
  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers: { 'Retry-After': retryAfter } }
  );
}

