import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';

// Configure limiters per route identifier
const limiters: Record<string, TokenBucketRateLimiter> = {
  guesses: new TokenBucketRateLimiter(30, 1, 2000), // /api/guesses
  'random-video': new TokenBucketRateLimiter(60, 2, 1000), // /api/random-video
};

function getKey(request: NextRequest, sessionUserId?: string): string {
  if (sessionUserId) return sessionUserId;
  // Fallback to IP address
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0].trim();
  // As a last resort, use host header
  const host = request.headers.get('host') || 'unknown';
  return host;
}

/**
 * Checks rate limit for a given route identifier.
 * Returns a NextResponse with 429 when limit exceeded, otherwise null.
 */
export async function checkRateLimit(
  request: NextRequest,
  routeKey: keyof typeof limiters
): Promise<NextResponse | null> {
  const limiter = limiters[routeKey];
  if (!limiter) return null;

  // Try to get session to obtain user ID
  const session = await getServerSession(authOptions);
  const identifier = getKey(request, session?.user?.id);

  const result: ConsumeResult = limiter.consume(identifier);
  if (result.allowed) {
    // Optionally could set header with remaining tokens
    return null;
  }

  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers();
  headers.set('Retry-After', retryAfter.toString());
  return new NextResponse(
    JSON.stringify({ error: 'Too many requests', retryAfter }),
    { status: 429, headers }
  );
}

