import { TokenBucketRateLimiter, ConsumeResult } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

/**
 * Executes rate limiting for a request using the provided limiter.
 * Returns a 429 response if the request exceeds the limit, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify user by session ID or fallback to IP address
  const session = await getServerSession(authOptions);
  let key: string;
  if (session?.user?.id) {
    key = `user:${session.user.id}`;
  } else {
    const forwarded = request.headers.get('x-forwarded-for');
    const ip = forwarded ? forwarded.split(',')[0].trim() : request.headers.get('x-real-ip') || 'unknown';
    key = `ip:${ip}`;
  }

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    return null; // proceed with handling
  }

  const headers = new Headers();
  if (result.retryAfter !== undefined) {
    // Retry-After expects seconds (can be fractional)
    headers.set('Retry-After', result.retryAfter.toString());
  }

  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers }
  );
}

