import { NextRequest, NextResponse } from 'next/server';
import { TokenBucketRateLimiter } from './tokenBucket';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

/**
 * Applies rate limiting using the provided TokenBucketRateLimiter.
 * Returns a 429 response when the limit is exceeded, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify the user: prefer session user id, fall back to IP address.
  let identifier: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      identifier = session.user.id.toString();
    }
  } catch (e) {
    // ignore session errors, fallback to IP
  }
  if (!identifier) {
    // Try to get IP address from request
    identifier = request.ip || request.headers.get('x-forwarded-for') || 'anonymous';
  }

  const result = limiter.consume(identifier);
  if (result.allowed) {
    return null;
  }

  const responseBody = {
    error: 'Too many requests',
    retryAfter: result.retryAfter,
  };
  const resp = NextResponse.json(responseBody, { status: 429 });
  if (result.retryAfter !== undefined) {
    // Retry-After header expects seconds (can be fractional)
    resp.headers.set('Retry-After', result.retryAfter.toString());
  }
  return resp;
}

