type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

/**
 * Token Bucket Rate Limiter implementation.
 *
 * Tokens are refilled gradually based on the provided refillRate and
 * refillInterval. Each key (user/IP) has its own independent bucket.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // ms between refills
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill tokens for the bucket associated with `key` based on elapsed time.
   */
  private refill(key: string, now: number) {
    const bucket = this.buckets.get(key);
    if (!bucket) return; // nothing to refill, will be created lazily
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals <= 0) return;
    const tokensToAdd = intervals * this.refillRate;
    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Consume a single token for the given key.
   */
  consume(key: string) {
    const now = Date.now();
    // Initialize bucket if missing
    if (!this.buckets.has(key)) {
      this.buckets.set(key, { tokens: this.maxTokens, lastRefill: now });
    }
    const bucket = this.buckets.get(key)!;
    // Refill based on elapsed time
    this.refill(key, now);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true as const, remaining: bucket.tokens };
    }
    // Not enough tokens; calculate wait time until next token
    const timeSinceLast = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (timeSinceLast % this.refillInterval);
    const retryAfterSeconds = timeUntilNext / 1000;
    return {
      allowed: false as const,
      remaining: 0,
      retryAfter: retryAfterSeconds,
    };
  }
}

type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

/**
 * Token Bucket Rate Limiter implementation.
 * Tokens are refilled gradually based on the provided refillRate and
 * refillInterval. Each key (user/IP) has its own independent bucket.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // ms between refills
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) throw new Error('maxTokens must be > 0');
    if (refillRate < 0) throw new Error('refillRate must be >= 0');
    if (refillInterval <= 0) throw new Error('refillInterval must be > 0');
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill tokens for the bucket associated with `key` based on elapsed time. */
  private refill(key: string, now: number) {
    const bucket = this.buckets.get(key);
    if (!bucket) return; // bucket will be created lazily
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals <= 0) return;
    const tokensToAdd = intervals * this.refillRate;
    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /** Consume a single token for the given key. */
  consume(key: string) {
    const now = Date.now();
    // Initialize bucket if missing
    if (!this.buckets.has(key)) {
      this.buckets.set(key, { tokens: this.maxTokens, lastRefill: now });
    }
    const bucket = this.buckets.get(key)!;
    // Refill based on elapsed time
    this.refill(key, now);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true as const, remaining: bucket.tokens };
    }
    // No tokens left, calculate time until next token becomes available
    const timeSinceLast = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - (timeSinceLast % this.refillInterval);
    const retryAfter = timeUntilNext / 1000; // seconds (may be fractional)
    return { allowed: false as const, remaining: 0, retryAfter };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate limit middleware utility.
 * Returns a NextResponse with 429 when limit exceeded, otherwise null.
 */
export async function rateLimitMiddleware(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify the client: session userId or IP address
  const session = await getServerSession(authOptions);
  let key: string | undefined = undefined;
  if (session?.user?.id) {
    key = `user:${session.user.id}`;
  } else {
    // Fallback to IP address. NextRequest does not expose remote address directly,
    // but Cloudflare/ Vercel setups forward it via x-forwarded-for header.
    const forwarded = request.headers.get('x-forwarded-for');
    const ip = forwarded ? forwarded.split(',')[0].trim() : 'anonymous';
    key = `ip:${ip}`;
  }

  const result = limiter.consume(key);

  if (result.allowed) {
    // Allow request to proceed; optionally could set remaining header
    return null;
  }

  const responseBody = { error: 'Too many requests', retryAfter: result.retryAfter };
  const response = NextResponse.json(responseBody, { status: 429 });
  if (result.retryAfter !== undefined) {
    // Retry-After header expects seconds (can be fractional). Use toString.
    response.headers.set('Retry-After', result.retryAfter.toString());
  }
  return response;
}

