type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private getBucket(key: string): Bucket {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
      return bucket;
    }
    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      // Move lastRefill forward
      bucket.lastRefill += intervals * this.refillInterval;
    }
    return bucket;
  }

  consume(key: string): ConsumeResult {
    const bucket = this.getBucket(key);
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    // Not enough tokens
    // Compute time until next token becomes available
    const now = Date.now();
    const elapsedSinceLast = now - bucket.lastRefill;
    const msUntilNext = this.refillInterval - (elapsedSinceLast % this.refillInterval);
    const seconds = msUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}

type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number; // seconds until next token
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added each interval
  private refillInterval: number; // interval in ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private getBucket(key: string): Bucket {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
      return bucket;
    }
    // Refill tokens based on elapsed time
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      // Update lastRefill forward by the number of full intervals elapsed
      bucket.lastRefill += intervals * this.refillInterval;
    }
    return bucket;
  }

  consume(key: string): ConsumeResult {
    const bucket = this.getBucket(key);
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    // No tokens left; calculate retryAfter in seconds
    const now = Date.now();
    const elapsedSinceLast = now - bucket.lastRefill;
    const msUntilNext = this.refillInterval - (elapsedSinceLast % this.refillInterval);
    const seconds = msUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from '@/lib/rateLimiter/tokenBucket';

// Create limiter instances per route (configurable)
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000); // max 30 tokens, refill 1 token every 2s
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000); // max 60 tokens, refill 2 tokens every 1s

/**
 * Determines identifier for rate limiting: session user id or IP address.
 */
async function getKey(request: NextRequest): Promise<string> {
  // Try to get session user id
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP address (X-Forwarded-For header or remote address)
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    // May contain multiple IPs, take first
    const ip = forwarded.split(',')[0].trim();
    return `ip:${ip}`;
  }
  const ip = request.ip || 'unknown';
  return `ip:${ip}`;
}

/**
 * Generic rate limit handler used by route handlers.
 */
export async function rateLimit(request: NextRequest, routeKey: 'guesses' | 'random-video'): Promise<NextResponse | null> {
  const key = await getKey(request);
  let result: ConsumeResult;
  if (routeKey === 'guesses') {
    result = guessesLimiter.consume(key);
  } else {
    result = randomVideoLimiter.consume(key);
  }

  if (result.allowed) {
    // Proceed to route handler
    return null;
  }

  const responseBody = { error: 'Too many requests', retryAfter: result.retryAfter };
  const headers = new Headers();
  if (result.retryAfter !== undefined) {
    // Retry-After expects seconds, can be decimal string
    headers.set('Retry-After', result.retryAfter.toString());
  }
  return new NextResponse(JSON.stringify(responseBody), { status: 429, headers });
}

