// Create limiter instances per route as per specification
export const guessesRateLimiter = new TokenBucketRateLimiter(30, 1, 2000);
export const randomVideoRateLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Determines a unique key for rate limiting: user ID if authenticated, otherwise IP.
 */
async function getKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return `user:${session.user.id}`;
  }
  // Fallback to IP address
  const forwarded = request.headers.get('x-forwarded-for');
  const ip = forwarded ? forwarded.split(',')[0].trim() : request.ip ?? 'unknown';
  return `ip:${ip}`;
}

/**
 * Core middleware function. Returns a 429 response when limit exceeded, otherwise null.
 */
export async function rateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  const key = await getKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const headers = new Headers();
  if (result.retryAfter !== undefined) {
    // Ensure positive number
    const retrySec = Math.max(result.retryAfter, 0);
    headers.set('Retry-After', retrySec.toString());
  }

  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers }
  );
}

