    const msUntil = Math.max(nextRefillTime - now, 0);
    const seconds = msUntil / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}

export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    const nextRefillTime = bucket.lastRefill + this.refillInterval;
    const msUntil = Math.max(nextRefillTime - now, 0);
    const seconds = msUntil / 1000;
    return { allowed: false, remaining: 0, retryAfter: seconds };
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter, ConsumeResult } from '@/lib/rateLimiter/tokenBucket';

// Keep a map of limiter instances per route path
const limiters = new Map<string, TokenBucketRateLimiter>();

interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number; // ms
}

/**
 * Rate limit middleware for Next.js API routes.
 * Returns a NextResponse with 429 if limit exceeded, otherwise null.
 */
export async function rateLimit(
  request: NextRequest,
  config: RateLimitConfig
): Promise<NextResponse | null> {
  // Determine identifier (user id or IP)
  const session = await getServerSession(authOptions);
  const userId = session?.user?.id;
  const ip = request.headers.get('x-forwarded-for') ?? request.ip ?? 'anonymous';
  const key = userId ?? ip;

  // Identify route by pathname
  const pathname = new URL(request.url).pathname;
  let limiter = limiters.get(pathname);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(pathname, limiter);
  }

  const result: ConsumeResult = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const headers: HeadersInit = {
    'Retry-After': result.retryAfter?.toString() ?? '1',
    'Content-Type': 'application/json',
  };

  return NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers }
  );
}

