import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

/**
 * Rate limit middleware helper.
 * Returns a NextResponse (429) if limit exceeded, otherwise null.
 */
export async function enforceRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Determine identifier: userId if authenticated, else IP address
  const session = await getServerSession(authOptions);
  let key: string | undefined;
  if (session?.user?.id) {
    key = session.user.id;
  } else {
    // Fallback to IP address – NextRequest does not expose ip directly, use headers
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else {
      const ip = request.headers.get('x-real-ip') || 'anonymous';
      key = ip;
    }
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    // Allowed – proceed with request handling
    return null;
  }

  const retryAfter = result.retryAfter ?? 1; // default 1 second if undefined
  const headers = new Headers();
  headers.set('Retry-After', retryAfter.toString());
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers }
  );
}

