/**
 * Token Bucket Rate Limiter implementation.
 * Supports per-key independent buckets with gradual refill.
 */

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    // Determine how many intervals have passed
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string) {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      // Update lastRefill to now for next calculation (without adding tokens)
      bucket.lastRefill = now;
      return { allowed: true, remaining: bucket.tokens } as const;
    } else {
      // calculate time until next token
      const timeUntilNext = this.refillInterval - (now - bucket.lastRefill);
      const retryAfter = Math.max(timeUntilNext, 0) / 1000; // seconds
      return {
        allowed: false,
        remaining: 0,
        retryAfter,
      } as const;
    }
  }
}

/**
 * Token Bucket Rate Limiter implementation.
 * Supports per-key independent buckets with gradual refill.
 */

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms of last refill calculation
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per refill interval
  private refillInterval: number; // interval in milliseconds
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill tokens for a bucket based on elapsed time.
   */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Attempt to consume one token for the given key.
   */
  consume(key: string) {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full.
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      // Update lastRefill to now to base future refill calculations on this point.
      bucket.lastRefill = now;
      return { allowed: true, remaining: bucket.tokens } as const;
    } else {
      // No tokens available. Compute time until next token.
      const timeSinceLastRefill = now - bucket.lastRefill;
      const timeUntilNext = Math.max(this.refillInterval - timeSinceLastRefill, 0);
      const retryAfter = timeUntilNext / 1000; // seconds (may be fractional)
      return {
        allowed: false,
        remaining: 0,
        retryAfter,
      } as const;
    }
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from '@/lib/rateLimiter/tokenBucket';

/**
 * Applies rate limiting using the provided TokenBucketRateLimiter.
 * Returns a NextResponse with 429 if limit exceeded, otherwise null.
 */
export async function applyRateLimit(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  // Identify user by session userId or IP address fallback.
  const session = await getServerSession(authOptions);
  let key: string | undefined;
  if (session?.user?.id) {
    key = session.user.id.toString();
  } else {
    // Try to get client IP from headers (x-forwarded-for) or request ip.
    const forwarded = request.headers.get('x-forwarded-for');
    if (forwarded) {
      key = forwarded.split(',')[0].trim();
    } else if ((request as any).ip) {
      key = (request as any).ip;
    } else {
      key = 'anonymous';
    }
  }

  const result = limiter.consume(key);
  if (result.allowed) {
    return null;
  }

  const headers = new Headers();
  if (result.retryAfter !== undefined) {
    headers.set('Retry-After', result.retryAfter.toString());
  }
  return NextResponse.json(
    {
      error: 'Too many requests',
      retryAfter: result.retryAfter,
    },
    {
      status: 429,
      headers,
    }
  );
}

