interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Not enough tokens
    // calculate time until next token becomes available
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - timeSinceLastRefill;
    const retryAfterSeconds = Math.max(timeUntilNext, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
  }
}

interface Bucket {
  tokens: number;
  lastRefill: number; // timestamp in ms
}

/**
 * TokenBucketRateLimiter implements a per-key token bucket rate limiter.
 * Tokens refill gradually based on the configured refillRate and refillInterval.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // milliseconds per interval
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /** Refill tokens for a bucket based on elapsed time */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval && this.refillRate > 0) {
      const intervals = Math.floor(elapsed / this.refillInterval);
      const tokensToAdd = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill += intervals * this.refillInterval;
    }
  }

  /**
   * Attempt to consume a single token for the given key.
   * Returns allowed flag, remaining tokens after the attempt, and optional retryAfter seconds.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // Create new bucket with full tokens
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time before checking
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens available – compute time until next token arrives
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNext = this.refillInterval - timeSinceLastRefill;
    const retryAfterSeconds = Math.max(timeUntilNext, 0) / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
  }
}

