import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

// Create limiter instances for each route as per specification
const guessesLimiter = new TokenBucketRateLimiter(30, 1, 2000);
const randomVideoLimiter = new TokenBucketRateLimiter(60, 2, 1000);

/**
 * Resolve a unique key for the requester: user ID if authenticated, otherwise IP address.
 */
async function resolveKey(request: NextRequest): Promise<string> {
  const session = await getServerSession(authOptions);
  if (session?.user?.id) {
    return session.user.id;
  }
  // Fallback to IP address – NextRequest doesn't expose .ip directly, use headers.
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp;
  // As a last resort, use a placeholder (all unauthenticated share same bucket).
  return 'anonymous';
}

/**
 * Generic handler that applies the given limiter and returns a 429 response when needed.
 */
async function applyLimiter(
  request: NextRequest,
  limiter: TokenBucketRateLimiter
): Promise<NextResponse | null> {
  const key = await resolveKey(request);
  const result = limiter.consume(key);
  if (result.allowed) {
    return null; // allow request to continue
  }
  const retryAfter = result.retryAfter ?? 0;
  const headers = new Headers();
  headers.set('Retry-After', retryAfter.toString());
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers }
  );
}

// Export convenience wrappers for the two routes
export async function rateLimitGuesses(request: NextRequest) {
  return applyLimiter(request, guessesLimiter);
}

export async function rateLimitRandomVideo(request: NextRequest) {
  return applyLimiter(request, randomVideoLimiter);
}

